use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    let n = cs.len()
    if n == 0 {
        return false
    }
    let mut start = 0
    if cs[0] == '-' {
        start = 1
    }
    if start >= n {
        return false
    }
    let mut i = start
    while i < n {
        if cs[i] < '0' || cs[i] > '9' {
            return false
        }
        i += 1
    }
    true
}

fn eval(line: string) -> string {
    let mut stack: Vec<int> = []
    for t in line.split(" ") {
        if t == "+" || t == "-" || t == "*" || t == "/" {
            let n = stack.len()
            if n < 2 {
                return "error: underflow"
            }
            let b: int = stack[n - 1]
            let a: int = stack[n - 2]
            let r: int = if t == "+" {
                a + b
            } else if t == "-" {
                a - b
            } else if t == "*" {
                a * b
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                a / b
            }
            stack.truncate(n - 2)
            stack.push(r)
        } else if is_int(t) {
            let v: int = t.parse::<int>().unwrap_or(0)
            stack.push(v)
        } else {
            return "error: token"
        }
    }
    if stack.len() != 1 {
        return "error: leftover"
    }
    "${stack[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println(eval(line.trim()))
    }
}

